from collections import defaultdict

def longest_consecutive_subarray(arr):
    n = len(arr)
    count = defaultdict(int)
    start = 0
    max_length = 0
    unique = 0
    twice = 0

    for end in range(n):
        count[arr[end]] += 1
        if count[arr[end]] == 1:
            unique += 1
        elif count[arr[end]] == 2:
            twice += 1

        while twice > unique:
            count[arr[start]] -= 1
            if count[arr[start]] == 1:
                unique -= 1
            elif count[arr[start]] == 0:
                twice -= 1
            start += 1

        if twice == unique:
            max_length = max(max_length, end - start + 1)

    return max_length

